import { BadRequestException, ConflictException, Injectable, NotFoundException, OnModuleDestroy, OnModuleInit, ServiceUnavailableException } from '@nestjs/common';
import { createCipheriv, createDecipheriv, createHash, randomBytes, timingSafeEqual } from 'node:crypto';
import { DatabaseService } from '../database/database.service';

type MetaConfig={client_id:string|null;secret_encrypted:string|null;api_version:string|null};
type Connection={id:string;user_id:string;token_encrypted:string;token_subject_id:string|null;token_expires_at:Date|null;granted_scopes:string[];status:string;last_checked_at:Date|null;last_error:string|null;disconnected_at:Date|null};
type PageConnection=Connection;
type GraphError={error?:{message?:string;code?:number;error_subcode?:number;type?:string;fbtrace_id?:string}};
type TokenResponse={access_token?:string;expires_in?:number;token_type?:string}&GraphError;
type PermissionResponse={data?:{permission?:string;status?:string}[]}&GraphError;
type AccountResponse={data?:{id?:string;account_id?:string;name?:string;account_status?:string|number;currency?:string;timezone_name?:string;timezone_offset_hours_utc?:number}[]}&GraphError;
type DebugResponse={data?:{app_id?:string;user_id?:string;expires_at?:number;scopes?:string[];is_valid?:boolean}}&GraphError;
type BusinessResponse={data?:{id?:string;name?:string}[]}&GraphError;

@Injectable()
export class MetaService implements OnModuleInit, OnModuleDestroy {
  constructor(private readonly db:DatabaseService) {}
  private managedSyncTimer:ReturnType<typeof setInterval>|null=null;
  onModuleInit(){this.managedSyncTimer=setInterval(()=>{void this.syncManagedAssets().catch(()=>undefined);void this.syncManagerPageConnections().catch(()=>undefined);},5*60_000);void this.syncManagedAssets().catch(()=>undefined);void this.syncManagerPageConnections().catch(()=>undefined);}
  onModuleDestroy(){if(this.managedSyncTimer)clearInterval(this.managedSyncTimer);}

  private encryptionKey(){const raw=process.env.APP_ENCRYPTION_KEY;if(!raw)throw new ServiceUnavailableException('APP_ENCRYPTION_KEY chưa được cấu hình.');const key=Buffer.from(raw,'base64');if(key.length!==32)throw new ServiceUnavailableException('APP_ENCRYPTION_KEY không hợp lệ.');return key;}
  private encrypt(value:string){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',this.encryptionKey(),iv),data=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return `${iv.toString('base64url')}.${cipher.getAuthTag().toString('base64url')}.${data.toString('base64url')}`;}
  private decrypt(value:string){const [ivPart,tagPart,dataPart]=value.split('.');if(!ivPart||!tagPart||!dataPart)throw new ServiceUnavailableException('Dữ liệu token mã hóa không hợp lệ.');const decipher=createDecipheriv('aes-256-gcm',this.encryptionKey(),Buffer.from(ivPart,'base64url'));decipher.setAuthTag(Buffer.from(tagPart,'base64url'));return Buffer.concat([decipher.update(Buffer.from(dataPart,'base64url')),decipher.final()]).toString('utf8');}
  private stateHash(value:string){return createHash('sha256').update(value).digest('hex');}
  private webOrigin(){const origin=(process.env.WEB_ORIGIN??'').split(',')[0]?.trim();if(!origin?.startsWith('https://'))throw new ServiceUnavailableException('WEB_ORIGIN HTTPS chưa được cấu hình cho Meta OAuth.');return origin.replace(/\/$/,'');}
  private redirectUri(){return `${this.webOrigin()}/api/v1/meta/oauth/callback`;}
  private safeRedirect(result:'success'|'denied'|'error',returnPath:'DEFAULT'|'META_MANAGER'='DEFAULT'){return `${this.webOrigin()}${returnPath==='META_MANAGER'?'/app/meta/manager':'/app/meta'}?oauth=${result}`;}
  private async config(){const {rows}=await this.db.query<MetaConfig>(`SELECT client_id,secret_encrypted,api_version FROM provider_integrations WHERE provider='META'`);const config=rows[0];if(!config?.client_id?.trim()||!config.secret_encrypted)return null;return {clientId:config.client_id.trim(),secret:this.decrypt(config.secret_encrypted),version:config.api_version||'v27.0'};}
  private graphUrl(version:string,path:string,params:Record<string,string>={}){const url=new URL(`https://graph.facebook.com/${version}/${path.replace(/^\//,'')}`);for(const [key,value] of Object.entries(params))url.searchParams.set(key,value);return url;}
  private authorizationUrl(version:string,params:Record<string,string>){const url=new URL(`https://www.facebook.com/${version}/dialog/oauth`);for(const [key,value] of Object.entries(params))url.searchParams.set(key,value);return url;}
  private async graph<T>(version:string,path:string,params:Record<string,string>={},method='GET'){
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),10_000);
    try {const response=await fetch(this.graphUrl(version,path,params),{method,signal:controller.signal});const body=await response.json().catch(()=>({}));if(!response.ok||(body as GraphError).error)throw new BadRequestException(this.graphMessage(body as GraphError,response.status));return body as T;}
    catch(error){if(error instanceof BadRequestException)throw error;if((error as {name?:string}).name==='AbortError')throw new ServiceUnavailableException('Meta API không phản hồi trong thời gian cho phép.');throw new ServiceUnavailableException('Không thể kết nối Meta API.');}
    finally {clearTimeout(timer);}
  }
  private graphMessage(body:GraphError,httpStatus?:number){const code=body.error?.code;const subcode=body.error?.error_subcode;const trace=body.error?.fbtrace_id;const reference=[httpStatus?`HTTP ${httpStatus}`:null,code!==undefined?`Meta ${code}${subcode===undefined?'':`/${subcode}`}`:null,trace?`trace ${trace}`:null].filter(Boolean).join(', ');const suffix=reference?` (${reference})`:'';if(code===190)return `Token Meta không hợp lệ hoặc đã hết hạn.${suffix}`;if(code===10||code===200)return `Meta chưa cấp quyền cần thiết cho ứng dụng hoặc người dùng.${suffix}`;if(httpStatus&&httpStatus>=500)return `Meta đang gặp lỗi máy chủ.${suffix}`;return `Meta từ chối yêu cầu kết nối. Kiểm tra lại cấu hình và quyền ứng dụng.${suffix}`;}
  private async connection(userId:string){const {rows}=await this.db.query<Connection>(`SELECT id,user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_checked_at,last_error,disconnected_at FROM meta_connections WHERE user_id=$1`,[userId]);return rows[0]??null;}
  private async pageConnection(userId:string){const {rows}=await this.db.query<PageConnection>(`SELECT id,user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_checked_at,last_error,disconnected_at FROM meta_page_oauth_connections WHERE user_id=$1`,[userId]);return rows[0]??null;}
  private async permissions(config:{clientId:string;secret:string;version:string},token:string){const permissions=await this.graph<PermissionResponse>(config.version,'me/permissions',{access_token:token});return (permissions.data??[]).filter(value=>value.status==='granted').map(value=>value.permission).filter((value):value is string=>Boolean(value));}
  private async verifiedToken(config:{clientId:string;secret:string;version:string},token:string){return this.graph<DebugResponse>(config.version,'debug_token',{input_token:token,access_token:`${config.clientId}|${config.secret}`});}
  private async storeAccounts(connectionId:string,ownerUserId:string,accounts:AccountResponse['data']){await this.db.transaction(async client=>{for(const account of accounts??[]){const accountId=account.account_id??account.id;if(!accountId)continue;await client.query(`INSERT INTO meta_ad_accounts(meta_connection_id,owner_user_id,account_id,account_name,account_status,currency,timezone_name,raw,last_synced_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,now()) ON CONFLICT(meta_connection_id,account_id) DO UPDATE SET owner_user_id=EXCLUDED.owner_user_id,account_name=EXCLUDED.account_name,account_status=EXCLUDED.account_status,currency=EXCLUDED.currency,timezone_name=EXCLUDED.timezone_name,raw=EXCLUDED.raw,last_synced_at=now(),updated_at=now()`,[connectionId,ownerUserId,accountId,account.name??null,account.account_status===undefined?null:String(account.account_status),account.currency??null,account.timezone_name??null,JSON.stringify({id:account.id??null,timezone_offset_hours_utc:account.timezone_offset_hours_utc??null})]);}});}
  private async synchronize(connection:Connection,config:{clientId:string;secret:string;version:string}){const token=this.decrypt(connection.token_encrypted);const granted=await this.permissions(config,token);if(!granted.includes('ads_read')){await this.db.query(`UPDATE meta_connections SET status='MISSING_PERMISSION',granted_scopes=$1,last_checked_at=now(),last_error='ads_read was not granted',updated_at=now() WHERE id=$2`,[granted,connection.id]);throw new BadRequestException('Meta chưa cấp quyền ads_read. Hãy kết nối lại và chấp thuận quyền đọc tài khoản quảng cáo.');}
    const accounts=await this.graph<AccountResponse>(config.version,'me/adaccounts',{fields:'id,account_id,name,account_status,currency,timezone_name,timezone_offset_hours_utc',limit:'100',access_token:token});await this.storeAccounts(connection.id,connection.user_id,accounts.data);await this.db.query(`UPDATE meta_connections SET status='CONNECTED',granted_scopes=$1,last_checked_at=now(),last_error=NULL,updated_at=now() WHERE id=$2`,[granted,connection.id]);await this.db.query(`UPDATE provider_integrations SET status='CONNECTED',last_checked_at=now(),last_error=NULL,updated_at=now() WHERE provider='META'`);return accounts.data?.length??0;}

  async status(userId:string){const integration=await this.db.query<{client_id:string|null;secret_encrypted:string|null;api_version:string|null}>(`SELECT client_id,secret_encrypted,api_version FROM provider_integrations WHERE provider='META'`);const app=integration.rows[0];const ready=Boolean(app?.client_id&&app.secret_encrypted);const connection=await this.connection(userId);const pending=await this.db.query<{expires_at:Date}>(`SELECT expires_at FROM meta_oauth_states WHERE user_id=$1 AND consumed_at IS NULL AND expires_at>now() ORDER BY created_at DESC LIMIT 1`,[userId]);const accounts=connection?await this.db.query(`SELECT id,account_id,account_name,account_status,currency,timezone_name,last_synced_at FROM meta_ad_accounts WHERE meta_connection_id=$1 AND owner_user_id=$2 ORDER BY account_name NULLS LAST,account_id`,[connection.id,userId]):{rows:[]};const expired=Boolean(connection?.token_expires_at&&connection.token_expires_at.getTime()<=Date.now());const connectionStatus=!ready?'NOT_CONFIGURED':expired?'TOKEN_EXPIRED':connection?.status==='CONNECTED'?'CONNECTED':connection?.status==='TOKEN_EXPIRED'?'TOKEN_EXPIRED':connection?.status==='MISSING_PERMISSION'?'MISSING_PERMISSION':connection?.status==='ERROR'?'ERROR':connection?.status==='DISCONNECTED'?'READY_TO_CONNECT':pending.rows[0]?'PENDING_OAUTH':'READY_TO_CONNECT';return {redirectUri:this.redirectUri(),app:{hasAppId:Boolean(app?.client_id),hasAppSecret:Boolean(app?.secret_encrypted),apiVersion:app?.api_version??'v27.0',requestedPermissions:['ads_read','ads_management'],ready},connection:{status:connectionStatus,pendingUntil:pending.rows[0]?.expires_at??null,hasPendingOAuth:Boolean(pending.rows[0]),expiresAt:connection?.token_expires_at??null,grantedPermissions:connection?.granted_scopes??[],lastCheckedAt:connection?.last_checked_at??null,lastError:connection?.last_error??null},accounts:accounts.rows};}

  async start(userId:string,purpose:'default'|'business_discovery'|'page_access'='default',managerSessionId?:string,returnPath:'DEFAULT'|'META_MANAGER'='DEFAULT'){const config=await this.config();if(!config)throw new BadRequestException('Meta Ads chưa sẵn sàng để kết nối. Vui lòng liên hệ quản trị viên.');const state=randomBytes(32).toString('base64url');const oauthMode=purpose==='page_access'?'PAGE':'ADS';await this.db.query(`UPDATE meta_oauth_states SET consumed_at=now() WHERE user_id=$1 AND consumed_at IS NULL`,[userId]);await this.db.query(`INSERT INTO meta_oauth_states(state_hash,user_id,expires_at,manager_session_id,return_path,oauth_mode) VALUES($1,$2,now()+interval '10 minutes',$3,$4,$5)`,[this.stateHash(state),userId,managerSessionId??null,returnPath,oauthMode]);const requested=purpose==='page_access'?['pages_show_list','pages_read_engagement']:(process.env.META_OAUTH_SCOPES??'ads_read,ads_management').split(',').map(value=>value.trim()).filter(Boolean);if(purpose!=='page_access')for(const permission of ['pages_show_list','pages_read_engagement'])if(!requested.includes(permission))requested.push(permission);if(purpose==='business_discovery'&&!requested.includes('business_management'))requested.push('business_management');const url=this.authorizationUrl(config.version,{client_id:config.clientId,redirect_uri:this.redirectUri(),state,response_type:'code',scope:requested.join(',')});return {authorizationUrl:url.toString()};}
  async cancelOAuth(userId:string){const result=await this.db.query(`UPDATE meta_oauth_states SET consumed_at=now() WHERE user_id=$1 AND consumed_at IS NULL AND expires_at>now() RETURNING id`,[userId]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,reason) VALUES('USER',$1,'META_OAUTH_CANCELLED','meta_connection','Pending OAuth request cancelled')`,[userId]);return {cancelled:result.rowCount??0};}
  async selectAccount(userId:string,accountId:string){const account=await this.db.query<{id:string;account_id:string;account_name:string|null}>(`SELECT id,account_id,account_name FROM meta_ad_accounts WHERE id=$1 AND owner_user_id=$2`,[accountId,userId]);if(!account.rows[0])throw new NotFoundException('Tài khoản quảng cáo không thuộc quyền truy cập của bạn.');await this.db.query('UPDATE users SET selected_meta_ad_account_id=$1,updated_at=now() WHERE id=$2',[accountId,userId]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_AD_ACCOUNT_SELECTED','meta_ad_account',$2,'Selected as active ad account')`,[userId,accountId]);return {selectedAccount:account.rows[0]};}
  private async managingAdmin(){const result=await this.db.query<Connection&{email:string}>(`SELECT c.id,c.user_id,c.token_encrypted,c.token_subject_id,c.token_expires_at,c.granted_scopes,c.status,c.last_checked_at,c.last_error,c.disconnected_at,u.email FROM meta_connections c JOIN users u ON u.id=c.user_id WHERE u.platform_role='SUPER_ADMIN' AND c.disconnected_at IS NULL ORDER BY c.updated_at DESC LIMIT 1`);return result.rows[0]??null;}
  async managerConfig(){const admin=await this.managingAdmin();if(!admin)return {ready:false,adminName:null,reason:'QAVIO chưa có Facebook Admin được kết nối.'};if(admin.token_expires_at&&admin.token_expires_at.getTime()<=Date.now())return {ready:false,adminName:null,reason:'Facebook Admin token đã hết hạn. Quản trị viên cần kết nối lại.'};const config=await this.config();if(!config)return {ready:false,adminName:null,reason:'Meta App chưa được cấu hình.'};try{const me=await this.graph<{name?:string}>(config.version,'me',{fields:'name',access_token:this.decrypt(admin.token_encrypted)});return {ready:true,adminName:me.name??'Facebook Admin của QAVIO',reason:null};}catch(error){const message=error instanceof Error?error.message:'Không thể xác minh Facebook Admin.';return {ready:false,adminName:null,reason:message};}}
  async managerPartnerConfig(){
    const result=await this.db.query<{business_portfolio_id:string|null;business_portfolio_name:string|null;system_user_token_encrypted:string|null;default_ad_account_id:string|null;last_checked_at:Date|null;last_error:string|null}>(`SELECT business_portfolio_id,business_portfolio_name,system_user_token_encrypted,default_ad_account_id,last_checked_at,last_error FROM meta_partner_config WHERE id=true`);
    const config=result.rows[0];
    const configured=Boolean(config?.business_portfolio_id&&config.system_user_token_encrypted&&config.default_ad_account_id);
    return {businessPortfolioId:config?.business_portfolio_id??null,businessPortfolioName:config?.business_portfolio_name??null,ready:configured&&Boolean(config?.last_checked_at)&&!config?.last_error,hasSystemUserToken:Boolean(config?.system_user_token_encrypted),hasExecutionAdAccount:Boolean(config?.default_ad_account_id),lastCheckedAt:config?.last_checked_at??null,reason:!config?.business_portfolio_id?'QAVIO chưa cấu hình Business Portfolio ID.':!config.system_user_token_encrypted?'QAVIO chưa cấu hình System User.':!config.default_ad_account_id?'QAVIO chưa chọn Ad Account vận hành.':config.last_error??'QAVIO chưa kiểm tra cấu hình Business Partner.'};
  }
  async managerPageRequests(userId:string){
    return (await this.db.query(`SELECT id,page_id,page_name,instagram_account_id,instagram_account_name,status,verification_method,last_error,verified_at,last_permission_check_at,created_at,updated_at FROM meta_partner_page_requests WHERE user_id=$1 ORDER BY created_at DESC`,[userId])).rows;
  }
  async managerPageOptions(userId:string){
    const config=await this.config();
    const connection=await this.pageConnection(userId);
    const setup=await this.db.query<{default_ad_account_id:string|null}>(`SELECT default_ad_account_id FROM meta_partner_config WHERE id=true`);
    const admin=await this.managingAdmin();
    const managerReady=Boolean(admin&&admin.status==='CONNECTED'&&!admin.disconnected_at&&(!admin.token_expires_at||admin.token_expires_at.getTime()>Date.now())&&admin.granted_scopes.includes('ads_management')&&admin.granted_scopes.includes('pages_show_list'));
    const managerReason=!admin||admin.disconnected_at?'Tài khoản quản lý Facebook QAVIO chưa kết nối.':admin.token_expires_at&&admin.token_expires_at.getTime()<=Date.now()?'Kết nối Facebook quản lý QAVIO đã hết hạn.':!admin.granted_scopes.includes('ads_management')?'Tài khoản quản lý QAVIO thiếu quyền ads_management.':!admin.granted_scopes.includes('pages_show_list')?'Tài khoản quản lý QAVIO cần kết nối lại và cấp quyền xem danh sách Trang.':null;
    if(!connection||connection.disconnected_at||connection.status!=='CONNECTED')return {connected:false,managerReady,managerReason,reason:'Kết nối Facebook của bạn chưa sẵn sàng. Hãy kết nối một lần để xác nhận quyền trên Trang.',pages:[],executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id)};
    if(connection.token_expires_at&&connection.token_expires_at.getTime()<=Date.now())return {connected:false,managerReady,managerReason,reason:'Kết nối Facebook đã hết hạn. Hãy kết nối lại một lần.',pages:[],executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id)};
    if(!connection.granted_scopes.includes('pages_show_list'))return {connected:false,managerReady,managerReason,reason:'Quyền xem danh sách Trang chưa được cấp. Kết nối lại Facebook và chấp thuận quyền Trang.',pages:[],executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id)};
    if(!config)throw new ServiceUnavailableException('Meta App chưa được cấu hình.');
    const result=await this.graph<{data?:{id?:string;name?:string;tasks?:string[];instagram_business_account?:{id?:string;username?:string}}[]}>(config.version,'me/accounts',{fields:'id,name,tasks,instagram_business_account{id,username}',limit:'100',access_token:this.decrypt(connection.token_encrypted)});
    const linked=await this.db.query<{external_asset_id:string}>(`SELECT external_asset_id FROM meta_user_assets WHERE qavio_user_id=$1 AND provider='META' AND asset_type='PAGE' AND authorization_status='CONNECTED'`,[userId]);
    const linkedIds=new Set(linked.rows.map(row=>row.external_asset_id));
    return {connected:true,managerReady,managerReason,executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id),pages:(result.data??[]).filter(page=>page.id&&page.name).map(page=>({id:page.id,name:page.name,tasks:page.tasks??[],instagram:page.instagram_business_account??null,connected:linkedIds.has(page.id!)}))};
  }
  async createManagerPageRequest(userId:string,pageId:string){
    const normalized=pageId.trim();
    if(!/^\d{3,}$/.test(normalized))throw new BadRequestException('Page ID không hợp lệ. Chỉ nhập ID Trang Facebook sau khi đã cấp quyền cho QAVIO.');
    try{
      const existing=await this.db.query<{id:string}>(`SELECT id FROM meta_partner_page_requests WHERE user_id=$1 AND page_id=$2 AND status<>'DISCONNECTED' ORDER BY created_at DESC LIMIT 1`,[userId,normalized]);
      if(existing.rows[0])return this.recheckManagerPageRequest(userId,existing.rows[0].id);
      const created=await this.db.query<{id:string}>(`INSERT INTO meta_partner_page_requests(user_id,page_id) VALUES($1,$2) RETURNING id`,[userId,normalized]);
      await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_PARTNER_PAGE_REQUESTED','meta_partner_page_request',$2,'Customer requested partner Page verification')`,[userId,created.rows[0].id]);
      return this.recheckManagerPageRequest(userId,created.rows[0].id);
    }catch(error){
      if((error as {code?:string}).code==='23505')throw new ConflictException('Trang này đã được liên kết hoặc đang được xác minh cho một khách hàng khác.');
      throw error;
    }
  }
  async recheckManagerPageRequest(userId:string,id:string){
    const request=await this.db.query<{id:string;page_id:string;user_id:string}>(`SELECT id,page_id,user_id FROM meta_partner_page_requests WHERE id=$1 AND user_id=$2`,[id,userId]);
    const item=request.rows[0];
    if(!item)throw new NotFoundException('Yêu cầu liên kết Trang không thuộc tài khoản của bạn.');
    const integration=await this.config();
    const customer=await this.pageConnection(userId);
    const admin=await this.managingAdmin();
    const setup=await this.db.query<{default_ad_account_id:string|null}>(`SELECT default_ad_account_id FROM meta_partner_config WHERE id=true`);
    const fail=async(status:string,reason:string)=>{await this.db.transaction(async client=>{await client.query(`UPDATE meta_partner_page_requests SET status=$1,last_error=$2,last_permission_check_at=now(),updated_at=now() WHERE id=$3`,[status,reason,id]);if(status==='PERMISSION_DENIED'||status==='TOKEN_EXPIRED')await client.query(`UPDATE meta_user_assets SET authorization_status='ACCESS_REVOKED',revoked_at=now(),last_permission_check_at=now(),updated_at=now() WHERE qavio_user_id=$1 AND provider='META' AND asset_type='PAGE' AND external_asset_id=$2 AND authorization_status='CONNECTED'`,[userId,item.page_id]);});return {connected:false,status,reason};};
    if(!integration)return fail('NOT_CONFIGURED','Meta App chưa được cấu hình.');
    if(!customer||customer.disconnected_at||customer.status!=='CONNECTED')return fail('WAITING_FOR_PERMISSION','Hãy kết nối Facebook của bạn để xác nhận quyền sử dụng Trang.');
    if(customer.token_expires_at&&customer.token_expires_at.getTime()<=Date.now())return fail('TOKEN_EXPIRED','Kết nối Facebook của bạn đã hết hạn. Hãy kết nối lại một lần.');
    if(!customer.token_subject_id)return fail('ERROR','Meta chưa trả về danh tính Facebook cho kết nối này; hãy kết nối lại để QAVIO xác minh đúng người.');
    if(!customer.granted_scopes.includes('pages_show_list'))return fail('PERMISSION_DENIED','Thiếu quyền xem danh sách Trang (pages_show_list). Hãy kết nối lại và cấp quyền Trang.');
    if(!admin||admin.status!=='CONNECTED'||admin.disconnected_at||(admin.token_expires_at&&admin.token_expires_at.getTime()<=Date.now()))return fail('NOT_CONFIGURED','Tài khoản quản lý Facebook QAVIO chưa sẵn sàng.');
    if(!admin.granted_scopes.includes('ads_management')||!admin.granted_scopes.includes('pages_show_list'))return fail('NOT_CONFIGURED','Tài khoản quản lý Facebook QAVIO cần cấp ads_management và quyền xem danh sách Trang; hãy kết nối lại OAuth Admin một lần.');
    try{
      const customerToken=this.decrypt(customer.token_encrypted);
      const adminToken=this.decrypt(admin.token_encrypted);
      const [customerPages,managerPage]=await Promise.all([
        this.graph<{data?:{id?:string;name?:string;tasks?:string[];instagram_business_account?:{id?:string;username?:string}}[]}>(integration.version,'me/accounts',{fields:'id,name,tasks,instagram_business_account{id,username}',limit:'100',access_token:customerToken}),
        this.graph<{id?:string;name?:string;tasks?:string[];instagram_business_account?:{id?:string;username?:string}}>(integration.version,item.page_id,{fields:'id,name,tasks,instagram_business_account{id,username}',access_token:adminToken})
      ]);
      const customerPage=(customerPages.data??[]).find(page=>page.id===item.page_id);
      if(!customerPage)return fail('PERMISSION_DENIED','Trang này không xuất hiện trong danh sách Trang mà tài khoản Facebook của bạn có quyền truy cập.');
      const customerTasks=customerPage.tasks??[];
      if(!customerTasks.some(task=>['ADVERTISE','MANAGE'].includes(task)))return fail('PERMISSION_DENIED','Tài khoản Facebook của bạn chưa có quyền quảng cáo hoặc quản lý trên Trang này.');
      const managerTasks=managerPage.tasks??[];
      if(!managerTasks.some(task=>['ADVERTISE','MANAGE'].includes(task)))return fail('WAITING_FOR_PERMISSION','QAVIO chưa được cấp quyền quảng cáo trên Trang này. Hãy chia sẻ quyền quảng cáo cho tài khoản quản lý QAVIO.');
      const pageName=managerPage.name??customerPage.name??null;
      const instagram=managerPage.instagram_business_account??customerPage.instagram_business_account??null;
      const verification={pageId:item.page_id,customerSubjectId:customer.token_subject_id,customerTasks,managerTasks,checkedAt:new Date().toISOString(),executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id)};
      await this.db.transaction(async client=>{
        await client.query(`UPDATE meta_partner_page_requests SET status='CONNECTED',page_name=$1,instagram_account_id=$2,instagram_account_name=$3,verification=$4::jsonb,verification_method='CUSTOMER_OAUTH_AND_QAVIO_ADMIN_PAGE_TASKS',last_error=NULL,verified_at=now(),last_permission_check_at=now(),updated_at=now() WHERE id=$5`,[pageName,instagram?.id??null,instagram?.username??null,JSON.stringify(verification),id]);
        await client.query(`INSERT INTO meta_user_assets(qavio_user_id,provider,asset_type,external_asset_id,asset_name,verification_method,granted_permissions,authorization_status,verified_at,last_permission_check_at) VALUES($1,'META','PAGE',$2,$3,'CUSTOMER_OAUTH_AND_QAVIO_ADMIN_PAGE_TASKS',$4::jsonb,'CONNECTED',now(),now()) ON CONFLICT(qavio_user_id,provider,asset_type,external_asset_id) DO UPDATE SET asset_name=EXCLUDED.asset_name,verification_method=EXCLUDED.verification_method,granted_permissions=EXCLUDED.granted_permissions,authorization_status='CONNECTED',revoked_at=NULL,last_permission_check_at=now(),updated_at=now()`,[userId,item.page_id,pageName,JSON.stringify(managerTasks)]);
        if(instagram?.id)await client.query(`INSERT INTO meta_user_assets(qavio_user_id,provider,asset_type,external_asset_id,asset_name,verification_method,granted_permissions,authorization_status,verified_at,last_permission_check_at) VALUES($1,'META','INSTAGRAM',$2,$3,'CUSTOMER_OAUTH_AND_QAVIO_ADMIN_PAGE_TASKS',$4::jsonb,'CONNECTED',now(),now()) ON CONFLICT(qavio_user_id,provider,asset_type,external_asset_id) DO UPDATE SET asset_name=EXCLUDED.asset_name,verification_method=EXCLUDED.verification_method,granted_permissions=EXCLUDED.granted_permissions,authorization_status='CONNECTED',revoked_at=NULL,last_permission_check_at=now(),updated_at=now()`,[userId,instagram.id,instagram.username??null,JSON.stringify(managerTasks)]);
      });
      await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('SYSTEM',$1,'META_PAGE_CONNECTED','meta_partner_page_request',$2,'Customer OAuth subject and QAVIO Admin Page tasks verified')`,[userId,id]);
      return {connected:true,status:'CONNECTED',page:{id:item.page_id,name:pageName},instagram,executionAdAccountConfigured:Boolean(setup.rows[0]?.default_ad_account_id)};
    }catch(error){
      const message=error instanceof Error?error.message:'Meta từ chối quyền với Trang.';
      const status=message.includes('Token Meta')?'TOKEN_EXPIRED':message.includes('Meta chưa cấp quyền')||message.includes('Meta từ chối')?'PERMISSION_DENIED':'ERROR';
      await this.db.query(`UPDATE meta_partner_page_requests SET status=$1,last_error=$2,last_permission_check_at=now(),updated_at=now() WHERE id=$3`,[status,message,id]);
      return {connected:false,status,reason:message};
    }
  }
  async managerOnboarding(userId:string){
    await this.expireManagerSessions(userId);
    let session=(await this.db.query(`SELECT id,status,expires_at,last_checked_at,last_error,completed_at FROM meta_manager_connection_sessions WHERE user_id=$1 ORDER BY created_at DESC LIMIT 1`,[userId])).rows[0]??null;
    if(session&&['PENDING_OAUTH','WAITING_FOR_META'].includes(session.status)){try{await this.syncManagedAssets();const connection=await this.connection(userId);if(connection?.status==='CONNECTED')await this.completeManagerSession(userId,session.id);else await this.db.query(`UPDATE meta_manager_connection_sessions SET status='WAITING_FOR_META',last_checked_at=now(),last_error='Đã kiểm tra quyền Facebook Admin. QAVIO cần bằng chứng ủy quyền Meta của USER để gắn đúng tài sản.',updated_at=now() WHERE id=$1`,[session.id]);}catch(error){const message=error instanceof Error?error.message:'Không thể kiểm tra quyền Meta lúc này.';await this.db.query(`UPDATE meta_manager_connection_sessions SET status='WAITING_FOR_META',last_checked_at=now(),last_error=$1,updated_at=now() WHERE id=$2`,[message,session.id]);}session=(await this.db.query(`SELECT id,status,expires_at,last_checked_at,last_error,completed_at FROM meta_manager_connection_sessions WHERE id=$1`,[session.id])).rows[0]??session;}
    const assets=await this.userAssets(userId);
    return {session,assets,requests:await this.managerRequests(userId)};
  }
  async startManagerOnboarding(userId:string){
    await this.expireManagerSessions(userId);
    const existing=await this.db.query<{id:string;status:string}>(`SELECT id,status FROM meta_manager_connection_sessions WHERE user_id=$1 AND status IN ('PENDING_OAUTH','WAITING_FOR_META') AND expires_at>now() ORDER BY created_at DESC LIMIT 1`,[userId]);
    const session=existing.rows[0]??(await this.db.query<{id:string;status:string}>(`INSERT INTO meta_manager_connection_sessions(user_id) VALUES($1) RETURNING id,status`,[userId])).rows[0];
    await this.db.query(`UPDATE meta_manager_connection_sessions SET status='WAITING_FOR_META',last_checked_at=now(),last_error=NULL,updated_at=now() WHERE id=$1`,[session.id]);
    return {sessionId:session.id,method:'ADMIN_MANAGED'};
  }
  private async expireManagerSessions(userId:string){await this.db.query(`UPDATE meta_manager_connection_sessions SET status='EXPIRED',last_error='Phiên kết nối đã hết hạn. Hãy bắt đầu lại.',updated_at=now() WHERE user_id=$1 AND expires_at<=now() AND status IN ('PENDING_OAUTH','WAITING_FOR_META')`,[userId]);}
  private async completeManagerSession(userId:string,sessionId:string){
    const owned=await this.db.query<{account_id:string}>(`SELECT account_id FROM meta_ad_accounts WHERE owner_user_id=$1`,[userId]);
    const admin=await this.managingAdmin();
    const adminAccounts=admin?await this.db.query<{account_id:string}>(`SELECT account_id FROM meta_ad_accounts WHERE meta_connection_id=$1`,[admin.id]):{rows:[]};
    const visible=new Set(adminAccounts.rows.map(row=>row.account_id));
    for(const account of owned.rows.filter(row=>visible.has(row.account_id))){
      const created=await this.db.query<{id:string}>(`INSERT INTO meta_admin_managed_requests(user_id,ad_account_id) VALUES($1,$2) ON CONFLICT DO NOTHING RETURNING id`,[userId,account.account_id]);
      if(created.rows[0])await this.recheckManagerRequest(userId,created.rows[0].id);
    }
    const linked=await this.db.query(`SELECT 1 FROM meta_user_assets WHERE qavio_user_id=$1 AND provider='META' AND asset_type='AD_ACCOUNT' AND authorization_status='CONNECTED' LIMIT 1`,[userId]);
    await this.db.query(`UPDATE meta_manager_connection_sessions SET status=$1,last_checked_at=now(),last_error=$2,completed_at=CASE WHEN $1='CONNECTED' THEN now() ELSE NULL END,updated_at=now() WHERE id=$3 AND user_id=$4`,[linked.rows[0]?'CONNECTED':'WAITING_FOR_META',linked.rows[0]?null:'Đang chờ Meta hiển thị tài sản đã được cấp quyền.',sessionId,userId]);
  }
  async managerRequests(userId:string){return (await this.db.query(`SELECT id,ad_account_id,verification->>'name' AS ad_account_name,status,last_error,verified_at,created_at,updated_at FROM meta_admin_managed_requests WHERE user_id=$1 ORDER BY created_at DESC`,[userId])).rows;}
  async refreshManager(userId:string){
    const result=await this.syncManagedAssets();
    const requests=await this.managerRequests(userId);
    return {synced:result.synced,requests};
  }
  async createManagerRequest(userId:string,input:string){const accountId=input.trim().replace(/^act_/,'');if(!/^\d{3,}$/.test(accountId))throw new BadRequestException('Ad Account ID không hợp lệ.');try{const result=await this.db.query<{id:string}>(`INSERT INTO meta_admin_managed_requests(user_id,ad_account_id) VALUES($1,$2) RETURNING id`,[userId,accountId]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id) VALUES('USER',$1,'META_ADMIN_MANAGED_REQUESTED','meta_admin_managed_request',$2)`,[userId,result.rows[0].id]);return this.recheckManagerRequest(userId,result.rows[0].id);}catch(error){if((error as {code?:string}).code==='23505')throw new ConflictException('Ad Account này đã được liên kết hoặc đang được xác minh cho người dùng khác.');throw error;}}
  async recheckManagerRequest(userId:string,id:string){const result=await this.db.query<{id:string;user_id:string;ad_account_id:string}>(`SELECT id,user_id,ad_account_id FROM meta_admin_managed_requests WHERE id=$1 AND user_id=$2`,[id,userId]);const item=result.rows[0];if(!item)throw new NotFoundException('Yêu cầu liên kết không thuộc tài khoản của bạn.');const ownership=await this.db.query(`SELECT 1 FROM meta_ad_accounts WHERE owner_user_id=$1 AND account_id=$2`,[userId,item.ad_account_id]);if(!ownership.rows[0]){await this.db.query(`UPDATE meta_admin_managed_requests SET status='NEEDS_USER_OAUTH',last_error='Cần xác thực Facebook OAuth để chứng minh quyền liên kết tài khoản này.',updated_at=now() WHERE id=$1`,[id]);return {connected:false,reason:'Cần xác thực Facebook OAuth để chứng minh bạn có quyền với tài khoản này.'};}const admin=await this.managingAdmin();const config=await this.config();if(!admin||!config)throw new BadRequestException('Facebook Admin của QAVIO chưa sẵn sàng để kiểm tra quyền.');try{const account=await this.graph<{id?:string;name?:string;permitted_tasks?:string[]}>(config.version,`act_${item.ad_account_id}`,{fields:'id,name,account_status,currency,timezone_name,permitted_tasks',access_token:this.decrypt(admin.token_encrypted)});await this.db.transaction(async client=>{await client.query(`UPDATE meta_admin_managed_requests SET status='CONNECTED',verification=$1::jsonb,last_error=NULL,verified_at=now(),updated_at=now() WHERE id=$2`,[JSON.stringify(account),id]);await client.query(`INSERT INTO meta_user_assets(qavio_user_id,provider,asset_type,external_asset_id,asset_name,verification_method,granted_permissions,authorization_status,verified_at,last_permission_check_at) VALUES($1,'META','AD_ACCOUNT',$2,$3,'ADMIN_AND_USER_OAUTH',$4::jsonb,'CONNECTED',now(),now()) ON CONFLICT(qavio_user_id,provider,asset_type,external_asset_id) DO UPDATE SET asset_name=EXCLUDED.asset_name,granted_permissions=EXCLUDED.granted_permissions,authorization_status='CONNECTED',revoked_at=NULL,last_permission_check_at=now(),updated_at=now()`,[userId,item.ad_account_id,account.name??null,JSON.stringify(account.permitted_tasks??[])]);});await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('SYSTEM',$1,'META_ADMIN_MANAGED_CONNECTED','meta_admin_managed_request',$2,'Admin and customer OAuth access verified')`,[userId,id]);return {connected:true};}catch(error){const message=error instanceof Error?error.message:'Meta từ chối quyền Admin trên Ad Account.';await this.db.query(`UPDATE meta_admin_managed_requests SET status='FAILED',last_error=$1,updated_at=now() WHERE id=$2`,[message,id]);throw error;}}
  async userAssets(userId:string,type?:string){const allowed=['AD_ACCOUNT','PAGE','INSTAGRAM'];if(type&&!allowed.includes(type))throw new BadRequestException('Loại tài sản không hợp lệ.');return (await this.db.query(`SELECT id,asset_type,external_asset_id,asset_name,granted_permissions,verified_at,last_permission_check_at FROM meta_user_assets WHERE qavio_user_id=$1 AND provider='META' AND authorization_status='CONNECTED' AND ($2::text IS NULL OR asset_type=$2) ORDER BY asset_type,asset_name NULLS LAST LIMIT 100`,[userId,type??null])).rows;}
  async adminAssets(pageInput?:string,searchInput?:string,status?:string){const page=Math.max(1,Number(pageInput)||1),limit=50,search=`%${searchInput?.trim()??''}%`;const count=await this.db.query<{count:string}>(`SELECT count(*) count FROM meta_user_assets WHERE provider='META' AND (asset_name ILIKE $1 OR external_asset_id ILIKE $1) AND ($2='' OR authorization_status=$2)`,[search,status??'']);const rows=await this.db.query(`SELECT a.id,u.email,a.asset_type,a.external_asset_id,a.asset_name,a.authorization_status,a.granted_permissions,a.verified_at,a.last_permission_check_at,a.revoked_at FROM meta_user_assets a JOIN users u ON u.id=a.qavio_user_id WHERE a.provider='META' AND (a.asset_name ILIKE $1 OR a.external_asset_id ILIKE $1) AND ($2='' OR a.authorization_status=$2) ORDER BY a.updated_at DESC LIMIT $3 OFFSET $4`,[search,status??'',limit,(page-1)*limit]);return {items:rows.rows,page,limit,total:+count.rows[0].count};}
  async managerAdminStatus(userId:string){const status=await this.status(userId);const users=await this.db.query<{count:string}>(`SELECT count(DISTINCT user_id) count FROM meta_admin_managed_requests WHERE status='CONNECTED'`);const linked=await this.db.query<{count:string}>(`SELECT count(*) count FROM meta_admin_managed_requests WHERE status='CONNECTED'`);return {...status,customersUsingConnections:+users.rows[0].count,connectedCustomerAccounts:+linked.rows[0].count};}
  private async syncManagerPageConnections(){const active=await this.db.query<{id:string;user_id:string}>(`SELECT id,user_id FROM meta_partner_page_requests WHERE status IN ('WAITING_FOR_PERMISSION','PENDING_VERIFICATION','CONNECTED') ORDER BY last_permission_check_at NULLS FIRST,updated_at ASC LIMIT 100`);for(const item of active.rows){try{await this.recheckManagerPageRequest(item.user_id,item.id);}catch{/* preserve last known status and retry on the next bounded sync */}}return {checked:active.rows.length};}
  async syncManagedAssets(){const admin=await this.managingAdmin();const config=await this.config();if(!admin||!config||admin.status!=='CONNECTED'||(admin.token_expires_at&&admin.token_expires_at.getTime()<=Date.now()))return {synced:false,reason:'ADMIN_OAUTH_UNAVAILABLE'};const token=this.decrypt(admin.token_encrypted);try{const accounts=await this.graph<AccountResponse>(config.version,'me/adaccounts',{fields:'id,account_id,name,account_status,currency,timezone_name,timezone_offset_hours_utc',limit:'500',access_token:token});await this.storeAccounts(admin.id,admin.user_id,accounts.data);const visible=new Set((accounts.data??[]).map(account=>account.account_id??account.id).filter((id):id is string=>Boolean(id)));const active=await this.db.query<{id:string;ad_account_id:string;user_id:string;status:string}>(`SELECT id,ad_account_id,user_id,status FROM meta_admin_managed_requests WHERE status IN ('PENDING_VERIFICATION','NEEDS_USER_OAUTH','CONNECTED')`);let connected=0,revoked=0;for(const request of active.rows){if(!visible.has(request.ad_account_id)){if(request.status==='CONNECTED'){await this.db.transaction(async client=>{await client.query(`UPDATE meta_admin_managed_requests SET status='ACCESS_REVOKED',last_error='Facebook Admin không còn quyền truy cập Ad Account này.',updated_at=now() WHERE id=$1`,[request.id]);await client.query(`UPDATE meta_user_assets SET authorization_status='ACCESS_REVOKED',revoked_at=now(),last_permission_check_at=now(),updated_at=now() WHERE qavio_user_id=$1 AND provider='META' AND asset_type='AD_ACCOUNT' AND external_asset_id=$2 AND authorization_status='CONNECTED'`,[request.user_id,request.ad_account_id]);});revoked++;}continue;}if(request.status!=='CONNECTED'){try{const result=await this.recheckManagerRequest(request.user_id,request.id);if(result.connected)connected++;}catch{/* status persisted by verifier */}}else await this.db.query(`UPDATE meta_user_assets SET last_permission_check_at=now(),updated_at=now() WHERE qavio_user_id=$1 AND provider='META' AND asset_type='AD_ACCOUNT' AND external_asset_id=$2 AND authorization_status='CONNECTED'`,[request.user_id,request.ad_account_id]);}await this.db.query(`UPDATE meta_connections SET last_checked_at=now(),last_error=NULL,updated_at=now() WHERE id=$1`,[admin.id]);return {synced:true,accountsVisible:visible.size,connected,revoked};}catch(error){const message=error instanceof Error?error.message:'Không thể đồng bộ quyền Meta Admin.';await this.db.query(`UPDATE meta_connections SET status='ERROR',last_error=$1,last_checked_at=now(),updated_at=now() WHERE id=$2`,[message,admin.id]);throw error;}}
  async partnerConfig(){const result=await this.db.query<{business_portfolio_id:string|null;business_portfolio_name:string|null;system_user_token_encrypted:string|null;default_ad_account_id:string|null;last_checked_at:Date|null;last_error:string|null}>('SELECT business_portfolio_id,business_portfolio_name,system_user_token_encrypted,default_ad_account_id,last_checked_at,last_error FROM meta_partner_config WHERE id=true');const row=result.rows[0];const systemUserConfigured=Boolean(row?.system_user_token_encrypted);return {businessPortfolioId:row?.business_portfolio_id??null,businessPortfolioName:row?.business_portfolio_name??null,defaultAdAccountId:row?.default_ad_account_id??null,systemUserConfigured,systemUserReady:Boolean(systemUserConfigured&&row?.last_checked_at&&!row?.last_error),lastCheckedAt:row?.last_checked_at??null,lastError:row?.last_error??null};}
  async createPartnerRequest(userId:string,input:{adAccountId:string;pageId?:string;instagramAccountId?:string}){const accountId=input.adAccountId.trim().replace(/^act_/,'');if(!/^\d{3,}$/.test(accountId))throw new BadRequestException('Ad Account ID không hợp lệ.');try{const request=await this.db.query<{id:string;status:string;ad_account_id:string}>(`INSERT INTO meta_partner_asset_requests(user_id,ad_account_id,page_id,instagram_account_id) VALUES($1,$2,$3,$4) RETURNING id,status,ad_account_id`,[userId,accountId,input.pageId?.trim()||null,input.instagramAccountId?.trim()||null]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id) VALUES('USER',$1,'META_PARTNER_LINK_REQUESTED','meta_partner_asset_request',$2)`,[userId,request.rows[0].id]);return await this.recheckPartnerRequest(userId,request.rows[0].id);}catch(error){if((error as {code?:string}).code==='23505')throw new ConflictException('Tài khoản này đang có yêu cầu liên kết hoặc đã được liên kết.');throw error;}}
  async partnerRequests(userId:string){return (await this.db.query(`SELECT id,ad_account_id,page_id,instagram_account_id,status,verification->>'name' AS ad_account_name,admin_note,verified_at,reviewed_at,created_at,updated_at FROM meta_partner_asset_requests WHERE user_id=$1 ORDER BY created_at DESC`,[userId])).rows;}
  async adminPartnerRequests(){return (await this.db.query(`SELECT r.*,u.email user_email FROM meta_partner_asset_requests r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC`)).rows;}
  async discoverPartnerBusinesses(userId:string){const config=await this.config();const connection=await this.connection(userId);if(!config||!connection||connection.disconnected_at)throw new BadRequestException('Super Admin chưa có kết nối Meta OAuth đang hoạt động.');if(connection.token_expires_at&&connection.token_expires_at.getTime()<=Date.now())throw new BadRequestException('Meta OAuth của Super Admin đã hết hạn. Hãy kết nối lại.');if(!connection.granted_scopes.includes('business_management'))throw new BadRequestException('Meta OAuth hiện tại chưa cấp business_management nên QAVIO không thể lấy danh sách Business Portfolio. Hãy kết nối lại bằng tài khoản có quyền quản trị Business Portfolio và cấp quyền này.');const businesses=await this.graph<BusinessResponse>(config.version,'me/businesses',{fields:'id,name',limit:'100',access_token:this.decrypt(connection.token_encrypted)});return {businesses:(businesses.data??[]).filter((business):business is {id:string;name:string}=>Boolean(business.id&&business.name))};}
  async configurePartner(actor:string,input:{businessPortfolioId:string;businessPortfolioName?:string;systemUserToken?:string;defaultAdAccountId?:string}){const id=input.businessPortfolioId.trim();if(!/^\d{5,}$/.test(id))throw new BadRequestException('Business Portfolio ID không hợp lệ.');const name=input.businessPortfolioName?.trim()||null;if(name&&name.length>255)throw new BadRequestException('Tên Business Portfolio quá dài.');const executionAccount=input.defaultAdAccountId?.trim().replace(/^act_/,'')||null;if(executionAccount&&!/^\d{3,}$/.test(executionAccount))throw new BadRequestException('Ad Account vận hành không hợp lệ.');const token=input.systemUserToken?.trim()?this.encrypt(input.systemUserToken.trim()):null;const result=await this.db.query(`INSERT INTO meta_partner_config(id,business_portfolio_id,business_portfolio_name,system_user_token_encrypted,default_ad_account_id,updated_by_user_id) VALUES(true,$1,$2,$3,$4,$5) ON CONFLICT(id) DO UPDATE SET business_portfolio_id=EXCLUDED.business_portfolio_id,business_portfolio_name=COALESCE(EXCLUDED.business_portfolio_name,meta_partner_config.business_portfolio_name),system_user_token_encrypted=COALESCE(EXCLUDED.system_user_token_encrypted,meta_partner_config.system_user_token_encrypted),default_ad_account_id=COALESCE(EXCLUDED.default_ad_account_id,meta_partner_config.default_ad_account_id),last_checked_at=NULL,last_error=NULL,updated_by_user_id=EXCLUDED.updated_by_user_id,updated_at=now() RETURNING business_portfolio_id,business_portfolio_name,default_ad_account_id,(system_user_token_encrypted IS NOT NULL) system_user_configured`,[id,name,token,executionAccount,actor]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity) VALUES('USER',$1,'META_PARTNER_CONFIGURED','meta_partner_config')`,[actor]);return result.rows[0];}
  async checkPartnerConfiguration(){const result=await this.db.query<{business_portfolio_id:string;system_user_token_encrypted:string;default_ad_account_id:string|null}>(`SELECT business_portfolio_id,system_user_token_encrypted,default_ad_account_id FROM meta_partner_config WHERE id=true`);const config=result.rows[0];if(!config?.business_portfolio_id)throw new BadRequestException('Chưa cấu hình QAVIO Business Portfolio ID.');if(!config.system_user_token_encrypted)throw new BadRequestException('Chưa cấu hình System User token.');if(!config.default_ad_account_id)throw new BadRequestException('Chưa chọn Ad Account vận hành của QAVIO.');try{const token=this.decrypt(config.system_user_token_encrypted);const integration=await this.config();if(!integration)throw new BadRequestException('Meta App chưa được cấu hình.');const [identity,debug,business,businessAssets,executionAccount]=await Promise.all([this.graph<{id?:string;name?:string}>(integration.version,'me',{fields:'id,name',access_token:token}),this.verifiedToken(integration,token),this.graph<{id?:string;name?:string}>(integration.version,config.business_portfolio_id,{fields:'id,name',access_token:token}),this.graph<{data?:unknown[]}>(integration.version,`${config.business_portfolio_id}/client_ad_accounts`,{fields:'id,name,account_status',limit:'1',access_token:token}),this.graph<{id?:string;account_status?:string|number;permitted_tasks?:string[]}>(integration.version,`act_${config.default_ad_account_id}`,{fields:'id,account_status,permitted_tasks',access_token:token})]);if(!debug.data?.is_valid)throw new BadRequestException('System User token không hợp lệ.');const granted=debug.data.scopes??[];const missing=['ads_read','ads_management'].filter(permission=>!granted.includes(permission));await this.db.query(`UPDATE meta_partner_config SET business_portfolio_name=COALESCE($1,business_portfolio_name),last_checked_at=now(),last_error=NULL,updated_at=now() WHERE id=true`,[business.name??null]);return {connected:true,systemUserName:identity.name??null,grantedPermissions:granted,missingPermissions:missing,canReadSharedAdAccounts:Array.isArray(businessAssets.data),executionAdAccount:{id:config.default_ad_account_id,status:executionAccount.account_status??null,permittedTasks:executionAccount.permitted_tasks??[]}};}catch(error){const message=error instanceof Error?error.message:'Không thể xác minh System User.';await this.db.query(`UPDATE meta_partner_config SET last_checked_at=now(),last_error=$1,updated_at=now() WHERE id=true`,[message]);throw error;}}
  async verifyPartnerRequest(id:string){const request=await this.db.query<{id:string;user_id:string;ad_account_id:string}>('SELECT id,user_id,ad_account_id FROM meta_partner_asset_requests WHERE id=$1',[id]);const item=request.rows[0];if(!item)throw new NotFoundException('Yêu cầu liên kết không tồn tại.');const userAccount=await this.db.query(`SELECT 1 FROM meta_ad_accounts WHERE owner_user_id=$1 AND account_id=$2`,[item.user_id,item.ad_account_id]);if(!userAccount.rows[0]){await this.db.query(`UPDATE meta_partner_asset_requests SET status='NEEDS_USER_OAUTH',updated_at=now() WHERE id=$1`,[id]);return {connected:false,reason:'Cần kết nối OAuth để xác nhận bạn có quyền với tài khoản này.'};}const config=await this.db.query<{business_portfolio_id:string;system_user_token_encrypted:string}>('SELECT business_portfolio_id,system_user_token_encrypted FROM meta_partner_config WHERE id=true');const row=config.rows[0];if(!row?.system_user_token_encrypted)return {connected:false,reason:'QAVIO chưa cấu hình System User để xác minh quyền đối tác.'};try{const account=await this.graph<Record<string,unknown>>('v27.0',`act_${item.ad_account_id}`,{fields:'id,name,account_status,currency,timezone_name,permitted_tasks,owner_business',access_token:this.decrypt(row.system_user_token_encrypted)});await this.db.query(`UPDATE meta_partner_asset_requests SET status='CONNECTED',verification=$1::jsonb,verified_at=now(),reviewed_at=now(),updated_at=now() WHERE id=$2`,[JSON.stringify(account),id]);await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('SYSTEM',$1,'META_PARTNER_LINK_CONNECTED','meta_partner_asset_request',$2,'User OAuth and QAVIO System User both verified access')`,[item.user_id,id]);return {connected:true};}catch(error){await this.db.query(`UPDATE meta_partner_asset_requests SET status='FAILED',updated_at=now() WHERE id=$1`,[id]);throw error;}}
  async recheckPartnerRequest(userId:string,id:string){const request=await this.db.query<{id:string}>('SELECT id FROM meta_partner_asset_requests WHERE id=$1 AND user_id=$2',[id,userId]);if(!request.rows[0])throw new NotFoundException('Yêu cầu liên kết không thuộc tài khoản của bạn.');return this.verifyPartnerRequest(id);}
  async approvePartnerRequest(actor:string,id:string){const result=await this.db.query(`UPDATE meta_partner_asset_requests SET status='APPROVED',reviewed_at=now(),reviewed_by_user_id=$1,updated_at=now() WHERE id=$2 AND status='VERIFIED' RETURNING id,user_id,ad_account_id`,[actor,id]);if(!result.rows[0])throw new BadRequestException('Yêu cầu phải được xác minh qua API trước khi duyệt.');await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id) VALUES('USER',$1,'META_PARTNER_LINK_APPROVED','meta_partner_asset_request',$2)`,[actor,id]);return result.rows[0];}

  async callback(state:string|undefined,code:string|undefined,error:string|undefined,_description:string|undefined){
    if(!state)return {redirect:this.safeRedirect('error')};
    let consumed:{userId:string;managerSessionId:string|null;returnPath:'DEFAULT'|'META_MANAGER';oauthMode:'ADS'|'PAGE'};
    try{consumed=await this.consumeState(state);}catch{return {redirect:this.safeRedirect('error')};}
    const {userId,managerSessionId,returnPath}=consumed;
    if(error||!code)return {redirect:this.safeRedirect(error?'denied':'error',returnPath)};
    try{
      const config=await this.config();if(!config)throw new BadRequestException('Meta App chưa được cấu hình.');
      const short=await this.graph<TokenResponse>(config.version,'oauth/access_token',{client_id:config.clientId,client_secret:config.secret,redirect_uri:this.redirectUri(),code});if(!short.access_token)throw new BadRequestException('Meta không trả về access token.');
      const long=await this.graph<TokenResponse>(config.version,'oauth/access_token',{grant_type:'fb_exchange_token',client_id:config.clientId,client_secret:config.secret,fb_exchange_token:short.access_token});const token=long.access_token??short.access_token;
      const debug=await this.verifiedToken(config,token);if(!debug.data?.is_valid)throw new BadRequestException('Meta token không hợp lệ.');
      const expiresAt=debug.data.expires_at?new Date(debug.data.expires_at*1000):(long.expires_in?new Date(Date.now()+long.expires_in*1000):null);const scopes=await this.permissions(config,token);
      if(consumed.oauthMode==='PAGE'){
        if(!scopes.includes('pages_show_list')){await this.upsertPageConnection(userId,token,debug.data.user_id??null,expiresAt,scopes,'MISSING_PERMISSION','pages_show_list was not granted');return {redirect:this.safeRedirect('error',returnPath)};}
        const pageConnection=await this.upsertPageConnection(userId,token,debug.data.user_id??null,expiresAt,scopes,'CONNECTED',null);
        await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_PAGE_OAUTH_CONNECTED','meta_page_oauth_connection',$2,'Page access OAuth token encrypted at rest')`,[userId,pageConnection.id]);
        return {redirect:this.safeRedirect('success',returnPath)};
      }
      if(!scopes.includes('ads_read')){await this.upsertConnection(userId,token,debug.data.user_id??null,expiresAt,scopes,'MISSING_PERMISSION','ads_read was not granted');return {redirect:this.safeRedirect('error',returnPath)};}
      const saved=await this.upsertConnection(userId,token,debug.data.user_id??null,expiresAt,scopes,'CONNECTED',null);await this.synchronize(saved,config);
      if(managerSessionId){try{await this.syncManagedAssets();await this.completeManagerSession(userId,managerSessionId);}catch{/* Page access is still verified by its own onboarding request. */}}
      await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_OAUTH_CONNECTED','meta_connection',$2,'OAuth completed; token encrypted at rest')`,[userId,saved.id]);
      return {redirect:this.safeRedirect('success',returnPath)};
    }catch{
      if(managerSessionId)await this.db.query(`UPDATE meta_manager_connection_sessions SET status='FAILED',last_error='Không thể hoàn tất OAuth Meta. Vui lòng thử lại.',updated_at=now() WHERE id=$1`,[managerSessionId]);
      await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,reason) VALUES('USER',$1,'META_OAUTH_FAILED','meta_connection','OAuth callback failed without persisting secrets')`,[userId]);
      return {redirect:this.safeRedirect('error',returnPath)};
    }
  }
  private async consumeState(state:string){const hash=this.stateHash(state);return this.db.transaction(async client=>{const result=await client.query<{user_id:string;state_hash:string;manager_session_id:string|null;return_path:'DEFAULT'|'META_MANAGER';oauth_mode:'ADS'|'PAGE'}>(`SELECT user_id,state_hash,manager_session_id,return_path,oauth_mode FROM meta_oauth_states WHERE state_hash=$1 AND consumed_at IS NULL AND expires_at>now() FOR UPDATE`,[hash]);const row=result.rows[0];if(!row||!timingSafeEqual(Buffer.from(row.state_hash),Buffer.from(hash)))throw new BadRequestException('OAuth state không hợp lệ hoặc đã hết hạn.');await client.query(`UPDATE meta_oauth_states SET consumed_at=now() WHERE state_hash=$1`,[hash]);return {userId:row.user_id,managerSessionId:row.manager_session_id,returnPath:row.return_path,oauthMode:row.oauth_mode};});}
  private async upsertConnection(userId:string,token:string,subject:string|null,expiresAt:Date|null,scopes:string[],status:string,lastError:string|null){const result=await this.db.query<Connection>(`INSERT INTO meta_connections(user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_error,last_checked_at,disconnected_at) VALUES($1,$2,$3,$4,$5,$6,$7,now(),NULL) ON CONFLICT(user_id) DO UPDATE SET token_encrypted=EXCLUDED.token_encrypted,token_subject_id=EXCLUDED.token_subject_id,token_expires_at=EXCLUDED.token_expires_at,granted_scopes=EXCLUDED.granted_scopes,status=EXCLUDED.status,last_error=EXCLUDED.last_error,last_checked_at=now(),disconnected_at=NULL,updated_at=now() RETURNING id,user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_checked_at,last_error,disconnected_at`,[userId,this.encrypt(token),subject,expiresAt,scopes,status,lastError]);return result.rows[0];}
  private async upsertPageConnection(userId:string,token:string,subject:string|null,expiresAt:Date|null,scopes:string[],status:string,lastError:string|null){const result=await this.db.query<PageConnection>(`INSERT INTO meta_page_oauth_connections(user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_error,last_checked_at,disconnected_at) VALUES($1,$2,$3,$4,$5,$6,$7,now(),NULL) ON CONFLICT(user_id) DO UPDATE SET token_encrypted=EXCLUDED.token_encrypted,token_subject_id=EXCLUDED.token_subject_id,token_expires_at=EXCLUDED.token_expires_at,granted_scopes=EXCLUDED.granted_scopes,status=EXCLUDED.status,last_error=EXCLUDED.last_error,last_checked_at=now(),disconnected_at=NULL,updated_at=now() RETURNING id,user_id,token_encrypted,token_subject_id,token_expires_at,granted_scopes,status,last_checked_at,last_error,disconnected_at`,[userId,this.encrypt(token),subject,expiresAt,scopes,status,lastError]);return result.rows[0];}
  async check(userId:string){const config=await this.config();const connection=await this.connection(userId);if(!config||!connection||connection.disconnected_at)throw new NotFoundException('Chưa có kết nối Meta đang hoạt động.');try{const total=await this.synchronize(connection,config);return {status:'CONNECTED',accountsSynced:total};}catch(error){const message=error instanceof BadRequestException?error.message:'Không thể kiểm tra kết nối Meta.';const status=message.includes('Token Meta')?'TOKEN_EXPIRED':'ERROR';await this.db.query(`UPDATE meta_connections SET status=$1,last_error=$2,last_checked_at=now(),updated_at=now() WHERE id=$3`,[status,message,connection.id]);await this.db.query(`UPDATE provider_integrations SET status='ERROR',last_error=$1,last_checked_at=now(),updated_at=now() WHERE provider='META'`,[message]);throw error;}}
  async sync(userId:string){return this.check(userId);}
  async disconnectManagerPageOAuth(userId:string){const config=await this.config();const connection=await this.pageConnection(userId);if(!connection||connection.disconnected_at)return {disconnected:true,revocation:'not_applicable'};let revocation='completed';if(config){try{await this.graph(config.version,'me/permissions',{access_token:this.decrypt(connection.token_encrypted)},'DELETE');}catch{revocation='provider_revoke_failed';}}await this.db.transaction(async client=>{await client.query(`UPDATE meta_page_oauth_connections SET status='DISCONNECTED',disconnected_at=now(),last_error=NULL,updated_at=now() WHERE id=$1`,[connection.id]);await client.query(`UPDATE meta_partner_page_requests SET status='DISCONNECTED',last_error='Facebook Page OAuth đã bị ngắt.',revoked_at=now(),last_permission_check_at=now(),updated_at=now() WHERE user_id=$1 AND status='CONNECTED'`,[userId]);await client.query(`UPDATE meta_user_assets SET authorization_status='ACCESS_REVOKED',revoked_at=now(),last_permission_check_at=now(),updated_at=now() WHERE qavio_user_id=$1 AND provider='META' AND asset_type IN ('PAGE','INSTAGRAM') AND authorization_status='CONNECTED'`,[userId]);await client.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_PAGE_OAUTH_DISCONNECTED','meta_page_oauth_connection',$2,$3)`,[userId,connection.id,revocation]);});return {disconnected:true,revocation};}
  async disconnect(userId:string){const config=await this.config();const connection=await this.connection(userId);if(!connection||connection.disconnected_at)return {disconnected:true,revocation:'not_applicable'};let revocation='completed';if(config){try{await this.graph(config.version,'me/permissions',{access_token:this.decrypt(connection.token_encrypted)},'DELETE');}catch{revocation='provider_revoke_failed';}}await this.db.transaction(async client=>{await client.query(`UPDATE meta_connections SET status='DISCONNECTED',disconnected_at=now(),last_error=NULL,updated_at=now() WHERE id=$1`,[connection.id]);await client.query(`UPDATE provider_integrations SET status='CONFIGURED_NOT_TESTED',last_error=NULL,updated_at=now() WHERE provider='META'`);await client.query(`DELETE FROM organization_meta_ad_accounts WHERE meta_ad_account_id IN (SELECT id FROM meta_ad_accounts WHERE meta_connection_id=$1)`,[connection.id]);await client.query(`INSERT INTO audit_logs(actor_type,actor_id,action,entity,entity_id,reason) VALUES('USER',$1,'META_OAUTH_DISCONNECTED','meta_connection',$2,$3)`,[userId,connection.id,revocation]);});return {disconnected:true,revocation};}
  async assign(userId:string,accountId:string,organizationId:string){const connection=await this.connection(userId);if(!connection||connection.status!=='CONNECTED')throw new BadRequestException('Cần kết nối Meta hợp lệ trước khi gán tài khoản.');const org=await this.db.query<{id:string}>(`SELECT id FROM organizations WHERE id=$1 AND status='ACTIVE'`,[organizationId]);if(!org.rows[0])throw new NotFoundException('Tổ chức không tồn tại hoặc đã bị khóa.');const account=await this.db.query<{id:string}>(`SELECT id FROM meta_ad_accounts WHERE id=$1 AND meta_connection_id=$2`,[accountId,connection.id]);if(!account.rows[0])throw new NotFoundException('Tài khoản quảng cáo không thuộc kết nối Meta hiện tại.');try{await this.db.query(`INSERT INTO organization_meta_ad_accounts(organization_id,meta_ad_account_id,connected_by_user_id) VALUES($1,$2,$3)`,[organizationId,accountId,userId]);}catch(error){if((error as {code?:string}).code==='23505')throw new ConflictException('Tài khoản quảng cáo này đã được gán cho một tổ chức khác.');throw error;}await this.db.query(`INSERT INTO audit_logs(actor_type,actor_id,organization_id,action,entity,entity_id,reason) VALUES('USER',$1,$2,'META_AD_ACCOUNT_ASSIGNED','meta_ad_account',$3,'Explicit Super Admin assignment')`,[userId,organizationId,accountId]);return {assigned:true};}
}
